/* @lc app=leetcode id=3878 lang=kotlin */ class Solution { fun countGoodSubarrays(nums: IntArray): Long = nums.size.let { n -> IntArray(30) { -1 }.let { lb -> HashMap<Int, Int>().let { le -> nums.indices.map { i -> maxOf((0..29).filter { nums[i] shr it and 1 == 0 }.maxOfOrNull { lb[it] } ?: -1, le[nums[i]] ?: -1).also { (0..29).filter { b -> nums[i] shr b and 1 == 1 }.forEach { b -> lb[b] = i } }.also { le[nums[i]] = i } } } }.let { left -> IntArray(30) { n }.let { nb -> (n - 1 downTo 0).map { i -> (0..29).filter { nums[i] shr it and 1 == 0 }.minOfOrNull { nb[it] }.let { r0 -> (r0 ?: n).also { (0..29).filter { b -> nums[i] shr b and 1 == 1 }.forEach { b -> nb[b] = i } } } }.reversed().let { right -> nums.indices.sumOf { (it - left[it]).toLong() * (right[it] - it) } } } } } }